<script setup>
import {onMounted,ref} from 'vue';import api from '../api';const list=ref([]),keyword=ref('');async function load(){list.value=(await api.get('/users',{params:{keyword:keyword.value}})).data.data}async function status(row){await api.put(`/users/${row.id}/status`,{enabled:!row.enabled});load()}async function role(row){await api.put(`/users/${row.id}/role`,{role:row.role})}onMounted(load)
</script>
<template><div class="page"><div class="page-title"><div><h2>用户与权限</h2><span class="muted">管理系统账号、角色和启用状态</span></div></div><div class="panel"><div class="toolbar"><el-input v-model="keyword" placeholder="用户名或姓名" style="width:260px"/><el-button @click="load">查询</el-button></div><el-table :data="list" stripe><el-table-column prop="username" label="用户名"/><el-table-column prop="realName" label="真实姓名"/><el-table-column prop="phone" label="联系电话"/><el-table-column label="角色" width="180"><template #default="s"><el-select v-model="s.row.role" @change="role(s.row)"><el-option label="管理员" value="ADMIN"/><el-option label="审核员" value="REVIEWER"/><el-option label="非遗艺人" value="ARTISAN"/><el-option label="普通用户" value="VIEWER"/></el-select></template></el-table-column><el-table-column label="账号状态" width="120"><template #default="s"><el-switch :model-value="s.row.enabled" @change="status(s.row)"/></template></el-table-column><el-table-column prop="createdAt" label="创建时间" width="190"/></el-table></div></div></template>
